const SCENE_NAME = 'cuc-quang'
const COMMAND = 'giao-dien-cuc-quang'

const { theme, problems } = makeColors({"label":"Cực quang","roles":{"accent":"#4FE3B0","danger":"#C0392B","success":"#2E8B57","warning":"#C27A1A","pro":"#8E5BD6"},"light":{"gray":{"anchors":{"surface-0":"#e6ecef","surface-1":"#f1f4f6","surface-2":"#fafbfc","text-primary":"#14262e","text-secondary":"#334e5b","text-muted":"#4e6774"}}},"dark":{"gray":{"anchors":{"surface-0":"#0d1316","surface-1":"#121a1e","surface-2":"#172126","surface-3":"#1d2930","text-primary":"#e9eff2","text-secondary":"#c3cfd5","text-muted":"#9fafb7"}}}})

// One look for both modes: the scene has no ground of its own, so the app's page colour from the palette,
